@startuml

class Elevator {
  + currentFloor : int
}

class ElevatorButton {
  + floorNumber : int
  + isLit : boolean
}

class FloorButton {
  + floorNumber : int
  + direction : string
  + isLit : boolean
}

Elevator "1" *-- "1..*" ElevatorButton
"1" -- "1..*" FloorButton : exists on

@enduml

